package com.asmj.marketplace.discovery;

import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.repository.UserAccountRepository;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class MarketplaceExtensionsController {
 private final MarketplaceExtensionListingRepository listings; private final MarketplaceExtensionRequestRepository requests; private final UserAccountRepository users;
 private static final Map<String,String> TYPES=Map.of("EVENT","events","COURSE","courses","WHOLESALE","wholesale","DELIVERY","delivery","FREELANCE","freelancers");
 private static final Map<String,String> TITLES=Map.of("EVENT","Events & ticket booking","COURSE","Courses & training","WHOLESALE","Wholesale & B2B enquiries","DELIVERY","Local delivery & logistics","FREELANCE","Freelance & professional portfolio");
 public MarketplaceExtensionsController(MarketplaceExtensionListingRepository l,MarketplaceExtensionRequestRepository r,UserAccountRepository u){listings=l;requests=r;users=u;}
 private UserAccount user(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 private String clean(String v,int n){if(v==null)return "";v=v.trim();return v.length()>n?v.substring(0,n):v;}
 private boolean validType(String type){return TYPES.containsKey(type);}
 private String browse(String type,String q,String city,Model m){List<MarketplaceExtensionListing> rows=listings.findByTypeAndStatusOrderByCreatedAtDesc(type,"APPROVED");if(q!=null&&!q.isBlank())rows.removeIf(x->!(safe(x.getTitle())+" "+safe(x.getCategory())+" "+safe(x.getDescription())+" "+safe(x.getSkills())).toLowerCase().contains(q.trim().toLowerCase()));if(city!=null&&!city.isBlank())rows.removeIf(x->x.getCity()==null||!x.getCity().equalsIgnoreCase(city.trim()));m.addAttribute("items",rows);m.addAttribute("type",type);m.addAttribute("moduleTitle",TITLES.get(type));m.addAttribute("q",q);m.addAttribute("city",city);return "extensions/list";}
 private String safe(String s){return s==null?"":s;}
 @GetMapping("/events") public String events(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("EVENT",q,city,m);}
 @GetMapping("/courses") public String courses(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("COURSE",q,city,m);}
 @GetMapping("/wholesale") public String wholesale(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("WHOLESALE",q,city,m);}
 @GetMapping("/delivery") public String delivery(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("DELIVERY",q,city,m);}
 @GetMapping("/freelancers") public String freelancers(@RequestParam(required=false)String q,@RequestParam(required=false)String city,Model m){return browse("FREELANCE",q,city,m);}
 @GetMapping("/marketplace/new/{type}") public String create(@PathVariable String type,Model m){if(!validType(type))return "error";m.addAttribute("type",type);m.addAttribute("moduleTitle",TITLES.get(type));m.addAttribute("listing",new MarketplaceExtensionListing());return "extensions/form";}
 @PostMapping("/marketplace/save") public String save(@RequestParam String type,@RequestParam String title,@RequestParam String category,@RequestParam String description,@RequestParam(required=false)String organisation,@RequestParam(required=false)String contactName,@RequestParam(required=false)String contactMobile,@RequestParam(required=false)String website,@RequestParam(required=false)String imageUrl,@RequestParam(required=false)String address,@RequestParam(required=false)String city,@RequestParam(required=false)String state,@RequestParam(required=false)String pinCode,@RequestParam(required=false)String deliveryArea,@RequestParam(required=false)String mode,@RequestParam(required=false)String skills,@RequestParam(required=false)String duration,@RequestParam(required=false)String schedule,@RequestParam(required=false)String venue,@RequestParam(required=false)String portfolioUrl,@RequestParam(required=false)String courseLevel,@RequestParam(required=false)String employmentType,@RequestParam(required=false)String price,@RequestParam(required=false)String minOrderQuantity,@RequestParam(required=false)Integer capacity,@RequestParam(required=false)Integer availableQuantity,@RequestParam(required=false)String eventDate,@RequestParam(required=false)String startDate,@RequestParam(required=false)String endDate,Authentication auth,RedirectAttributes ra){if(!validType(type))return "redirect:/";MarketplaceExtensionListing x=new MarketplaceExtensionListing();x.setType(type);x.setOwnerUserId(user(auth).getId());x.setTitle(clean(title,150));x.setCategory(clean(category,100));x.setDescription(clean(description,5000));x.setOrganisation(clean(organisation,160));x.setContactName(clean(contactName,100));x.setContactMobile(clean(contactMobile,20));x.setWebsite(clean(website,300));x.setImageUrl(clean(imageUrl,1000));x.setAddress(clean(address,300));x.setCity(clean(city,80));x.setState(clean(state,80));x.setPinCode(clean(pinCode,10));x.setDeliveryArea(clean(deliveryArea,500));x.setMode(clean(mode,80));x.setSkills(clean(skills,1000));x.setDuration(clean(duration,100));x.setSchedule(clean(schedule,300));x.setVenue(clean(venue,250));x.setPortfolioUrl(clean(portfolioUrl,500));x.setCourseLevel(clean(courseLevel,80));x.setEmploymentType(clean(employmentType,80));try{if(price!=null&&!price.isBlank())x.setPrice(new BigDecimal(price));if(minOrderQuantity!=null&&!minOrderQuantity.isBlank())x.setMinOrderQuantity(new BigDecimal(minOrderQuantity));if(eventDate!=null&&!eventDate.isBlank())x.setEventDate(LocalDate.parse(eventDate));if(startDate!=null&&!startDate.isBlank())x.setStartDate(LocalDate.parse(startDate));if(endDate!=null&&!endDate.isBlank())x.setEndDate(LocalDate.parse(endDate));}catch(Exception ex){ra.addFlashAttribute("error","Please check the entered price or date fields.");return "redirect:/marketplace/new/"+type;}x.setCapacity(capacity);x.setAvailableQuantity(availableQuantity);if("EVENT".equals(type)&&capacity!=null&&capacity>0&&x.getAvailableQuantity()==null)x.setAvailableQuantity(capacity);if(x.getTitle().isBlank()||x.getCategory().isBlank()||x.getDescription().isBlank()){ra.addFlashAttribute("error","Title, category and description are required.");return "redirect:/marketplace/new/"+type;}x.setStatus("PENDING");x.setCreatedAt(Instant.now());x.setUpdatedAt(Instant.now());listings.save(x);ra.addFlashAttribute("success","Your submission is pending admin approval.");return "redirect:/my-marketplace-listings";}
 @PostMapping("/marketplace/{id}/request") public synchronized String request(@PathVariable String id,@RequestParam(required=false)String message,@RequestParam(required=false)String quantity,@RequestParam(required=false)String pickupAddress,@RequestParam(required=false)String dropAddress,Authentication auth,RedirectAttributes ra){MarketplaceExtensionListing l=listings.findById(id).orElse(null);if(l==null||!"APPROVED".equals(l.getStatus()))return "redirect:/";UserAccount u=user(auth);MarketplaceExtensionRequest r=new MarketplaceExtensionRequest();r.setListingId(id);r.setType(l.getType());r.setRequesterUserId(u.getId());r.setRequesterName(u.getFullName());r.setRequesterEmail(u.getEmail());r.setMessage(clean(message,2000));r.setQuantity(clean(quantity,80));if("EVENT".equals(l.getType())){int ticketCount=1;try{ticketCount=(quantity==null||quantity.isBlank())?1:Integer.parseInt(quantity);}catch(NumberFormatException ex){ra.addFlashAttribute("error","Enter a valid ticket quantity.");return "redirect:/events";}if(ticketCount<1||(l.getAvailableQuantity()!=null&&ticketCount>l.getAvailableQuantity())){ra.addFlashAttribute("error","Requested ticket quantity is not available.");return "redirect:/events";}if(l.getAvailableQuantity()!=null){l.setAvailableQuantity(l.getAvailableQuantity()-ticketCount);listings.save(l);}r.setQuantity(String.valueOf(ticketCount));}r.setPickupAddress(clean(pickupAddress,300));r.setDropAddress(clean(dropAddress,300));r.setStatus("SUBMITTED");requests.save(r);ra.addFlashAttribute("success",switch(l.getType()){case "EVENT"->"Event registration request submitted. The organizer will confirm availability and payment instructions.";case "COURSE"->"Course enrolment enquiry submitted.";case "WHOLESALE"->"Wholesale quotation request sent.";case "DELIVERY"->"Delivery request submitted for provider confirmation.";default->"Project enquiry sent to the professional.";});return "redirect:/"+TYPES.get(l.getType());}
 @GetMapping("/my-marketplace-listings") public String mine(Authentication a,Model m){m.addAttribute("items",listings.findByOwnerUserIdOrderByCreatedAtDesc(user(a).getId()));m.addAttribute("requests",requests.findByRequesterUserIdOrderByCreatedAtDesc(user(a).getId()));return "extensions/mine";}
 @GetMapping("/admin/marketplace-extensions") public String admin(Model m){m.addAttribute("items",listings.findAll());m.addAttribute("requests",requests.findAll());return "extensions/admin";}
 @PostMapping("/admin/marketplace-extensions/{id}/status") public String status(@PathVariable String id,@RequestParam String status,RedirectAttributes ra){if(!Set.of("APPROVED","REJECTED","SUSPENDED","CLOSED").contains(status))return "redirect:/admin/marketplace-extensions";listings.findById(id).ifPresent(x->{x.setStatus(status);x.setUpdatedAt(Instant.now());listings.save(x);});ra.addFlashAttribute("success","Marketplace submission status updated.");return "redirect:/admin/marketplace-extensions";}
 @PostMapping("/admin/marketplace-extension-requests/{id}/status") public String requestStatus(@PathVariable String id,@RequestParam String status,RedirectAttributes ra){if(!Set.of("CONFIRMED","IN_PROGRESS","COMPLETED","CANCELLED","QUOTED").contains(status))return "redirect:/admin/marketplace-extensions";requests.findById(id).ifPresent(x->{String previous=x.getStatus();if("EVENT".equals(x.getType())&&"SUBMITTED".equals(previous)&&"CANCELLED".equals(status)){listings.findById(x.getListingId()).ifPresent(event->{if(event.getAvailableQuantity()!=null){int count=1;try{count=Integer.parseInt(x.getQuantity());}catch(Exception ignored){}event.setAvailableQuantity(event.getAvailableQuantity()+count);listings.save(event);}});}x.setStatus(status);if("CONFIRMED".equals(status)&&"EVENT".equals(x.getType())&&(x.getTicketReference()==null||x.getTicketReference().isBlank()))x.setTicketReference("ASMJ-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT));x.setUpdatedAt(Instant.now());requests.save(x);});ra.addFlashAttribute("success","Request status updated.");return "redirect:/admin/marketplace-extensions";}
 @GetMapping("/marketplace-extension-requests") public String myRequests(Authentication a,Model m){m.addAttribute("requests",requests.findByRequesterUserIdOrderByCreatedAtDesc(user(a).getId()));return "extensions/requests";}
}
